   "titleVi": "而已 — chỉ vậy thôi",
   "giaiThich": "Trợ từ cuối câu, ý mức độ chẳng có gì đặc biệt. Kết hợp 才 + số lượng + 而已 nhấn mạnh số lượng rất ít, ảnh hưởng không đáng kể."
