     "formula": "「V住」的意思是使動作穩定不變，像：「記住」、「拿住」、「停住」、「站住」等等。「V得住, V不住 」的意思是「可以V住, 不能V住」。 III.改V表示說話的人因為不想做某件事，或得不到想要的結果，而把原來做的事換成「改」後面的動作或行為「V」。 1. A：不好意思，昨天我幫你訂十二月二十四日上午九點往日本的",
